            if (settings.Ai.Enabled && !settings.Ai.Onboarded)
            {
                ShowWelcomeOnboarding();
            }

            if (e.Args.Contains("--settings"))
            {
                _manager.OpenSettings();
            }

            if (e.Args.Contains("--chat"))
            {
                ShowChatWindow();
            }
        }

        var benchIndex = Array.FindIndex(e.Args, a => a.StartsWith("--bench-"));
